    app_handle: AppHandle,
    input: config::instance::CreateInstanceInput,
) -> Result<config::instance::DshInstance, String> {
    ensure_launcher_update_context()?;
    if let Some(id) = input.runtime_id.as_deref() {
        config::by_id(&app_handle, id)?;
