    let _operation_guard = instance_operation_lock().lock().await;
    let (home, profile, _) = guard_provider_write(&app_handle, &instance_id).await?;
    // 应用前重新生成写入内容：模板或草稿在预览之后变过，脚本内的摘要比对就会失配并中止。
