    #[test]
    fn frontend_provider_draft_arrives_with_its_credential_intent() {
        let draft: super::ProviderDraft = serde_json::from_value(serde_json::json!({
            "template": {
                "id": "deepseek",
                "name": "DeepSeek",
                "baseUrl": "",
                "protocol": "",
                "modelId": "",
                "models": [],
                "modelOverrides": [{ "id": "chat", "contextWindow": 64000 }],
                "selection": "all",
                "defaultForNew": false,
                "kind": "catalog",
            },
            "apiKey": null,
            "credentialMode": "keep",
