        let legacy: super::ProviderDraft = serde_json::from_value(serde_json::json!({
            "template": { "id": "g", "name": "G" },
            "apiKey": "k",
        }))
        .expect("a draft without credentialMode stays valid");
        assert!(legacy.credential_mode.is_none());
