/// 启动守卫：并发调用 `launch` 时只允许一个真正拉起 dsh 进程
static LAUNCH_GUARD: AtomicBool = AtomicBool::new(false);
/// 当前进程内由桌面端创建的 Harness 根进程 PID；0 表示没有持有的实例。
static OWNED_PROCESS_ID: AtomicU32 = AtomicU32::new(0);
/// 当前实例本次启动实际分配的端口；停止后归零。
static RUNTIME_PORT: AtomicU32 = AtomicU32::new(0);
/// 实例宿主被启动器指定使用固定端口（协作编排先分配端口再启动）。
static REQUESTED_PORT: AtomicU32 = AtomicU32::new(0);
/// DSH 启动时输出的本次 Web 入口。新版本会在 query 中携带临时认证 token，
/// 因此只保存在实例宿主进程内存中，不写入配置或日志。
static RUNTIME_WEB_URL: OnceLock<Mutex<Option<String>>> = OnceLock::new();
/// Windows 进程句柄用于确认 PID 仍指向原进程，消除 PID 复用误杀窗口。
#[cfg(windows)]
static OWNED_PROCESS_HANDLE: AtomicUsize = AtomicUsize::new(0);

struct LaunchGuard;

impl Drop for LaunchGuard {
    fn drop(&mut self) {
        LAUNCH_GUARD.store(false, Ordering::SeqCst);
    }
}

/// 从起始端口向上查找第一个空闲端口，绝不结束未知的端口占用进程。
pub fn find_available_port(start: u16) -> Result<u16, String> {
    let mut port = start;
    loop {
        if !is_port_in_use(port) {
            return Ok(port);
        }
        log::warn!("Port {port} is occupied, trying the next port");
        port = port.checked_add(1).ok_or_else(|| {
            "PORT_EXHAUSTED: no available TCP port after the configured port".to_string()
        })?;
    }
}

/// 指定本次启动使用的固定端口；0 表示未指定（沿用自动探测）。
pub fn set_requested_port(port: u16) {
    REQUESTED_PORT.store(port as u32, Ordering::SeqCst);
}

fn requested_port() -> Option<u16> {
    let port = REQUESTED_PORT.load(Ordering::SeqCst);
    if port == 0 {
        None
    } else {
        u16::try_from(port).ok()
    }
}

/// dsh 版本是否支持 `--no-open` 标志。
///
/// 0.1.0-rc.8 起 `dsh web` 默认在系统浏览器打开 UI（桌面端内嵌 WebView，
/// 不希望每次启动都弹浏览器），并新增 `--no-open` 关闭该行为。更早的 rc
/// 版本没有这个标志，commander 会把未知选项当作错误、导致 web profile
/// 启动失败，因此追加标志前必须与完整版本 0.1.0-rc.8 比较。无法解析的
/// 版本号保守按不支持处理。
fn version_supports_no_open(version: &str) -> bool {
    let version = version.trim().trim_start_matches('v');
    let (core, prerelease) = match version.split_once('-') {
        Some((core, prerelease)) => (core, Some(prerelease)),
        None => (version, None),
    };
    let mut parts = core.split('.');
    let core = match (parts.next(), parts.next(), parts.next(), parts.next()) {
        (Some(major), Some(minor), Some(patch), None) => match (
            major.parse::<u32>(),
            minor.parse::<u32>(),
            patch.parse::<u32>(),
        ) {
            (Ok(major), Ok(minor), Ok(patch)) => (major, minor, patch),
            _ => return false,
        },
        _ => return false,
    };

    match core.cmp(&(0, 1, 0)) {
        std::cmp::Ordering::Greater => true,
        std::cmp::Ordering::Less => false,
        std::cmp::Ordering::Equal => match prerelease {
            None => true,
            Some(value) => value
                .strip_prefix("rc.")
                .and_then(|rc| rc.parse::<u32>().ok())
                .is_some_and(|rc| rc >= 8),
        },
    }
}

fn dsh_web_capability_key(app_handle: &tauri::AppHandle) -> String {
    let metadata = fs::metadata(config::get_dsh_binary_path(app_handle)).ok();
    let file_len = metadata.as_ref().map_or(0, std::fs::Metadata::len);
    let modified = metadata
        .and_then(|value| value.modified().ok())
        .and_then(|value| value.duration_since(std::time::UNIX_EPOCH).ok())
        .map_or(0, |value| value.as_secs());
    format!(
        "{}:{}:{file_len}:{modified}",
        config::get_dsh_version(app_handle).unwrap_or_default(),
        config::get_dsh_pkg_commit(app_handle).unwrap_or_default()
    )
}

fn probe_no_open_capability(app_handle: &tauri::AppHandle) -> Option<bool> {
    let node = config::get_dsh_node_path(app_handle);
    let dsh = config::get_dsh_binary_path(app_handle);
    if !node.is_file() || !dsh.is_file() {
        return None;
    }

    let mut command = Command::new(node);
    command
        .arg(dsh)
        .args(["web", "--help"])
        .env("DSH_HOME", config::get_dsh_data_path(app_handle))
        .current_dir(config::get_dsh_working_dir(app_handle))
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        command.creation_flags(0x08000000);
    }

    let mut child = command.spawn().ok()?;
    let stdout = child.stdout.take();
    let stderr = child.stderr.take();
    let stdout_reader = std::thread::spawn(move || {
        let mut output = String::new();
        if let Some(mut stream) = stdout {
            let _ = stream.read_to_string(&mut output);
        }
        output
    });
    let stderr_reader = std::thread::spawn(move || {
        let mut output = String::new();
        if let Some(mut stream) = stderr {
            let _ = stream.read_to_string(&mut output);
        }
        output
    });
    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(3);
    let mut timed_out = false;
    loop {
        match child.try_wait() {
            Ok(Some(_)) => break,
            Ok(None) if std::time::Instant::now() < deadline => {
                std::thread::sleep(std::time::Duration::from_millis(25));
            }
            Ok(None) => {
                let _ = child.kill();
                let _ = child.wait();
                log::warn!("DSH Web capability probe timed out");
                timed_out = true;
                break;
            }
            Err(error) => {
                let _ = child.kill();
                log::warn!("DSH Web capability probe failed: {error}");
                return None;
            }
        }
    }

    let output = format!(
        "{}{}",
        stdout_reader.join().unwrap_or_default(),
        stderr_reader.join().unwrap_or_default()
    );
    if output.contains("--no-open") {
        Some(true)
    } else if timed_out {
        None
    } else {
        Some(false)
    }
}

/// Detect once per installed DSH runtime and persist the result. A failed
/// probe falls back to the complete-version compatibility rule.
pub fn refresh_web_capabilities(app_handle: &tauri::AppHandle) -> bool {
    let key = dsh_web_capability_key(app_handle);
    let mut setting = config::get_store_dat_setting(app_handle);
    if setting.dsh_web_capability_key.as_deref() == Some(key.as_str()) {
        if let Some(supported) = setting.dsh_web_supports_no_open {
            return supported;
        }
    }

    let detected = probe_no_open_capability(app_handle);
    let supported = detected.unwrap_or_else(|| {
        config::get_dsh_version(app_handle)
            .as_deref()
            .is_some_and(version_supports_no_open)
    });
    setting.dsh_web_capability_key = Some(key);
    setting.dsh_web_supports_no_open = Some(supported);
    config::set_store_dat_setting(app_handle, setting);
    log::info!(
        "DSH Web --no-open capability: {} ({})",
        supported,
        if detected.is_some() {
            "detected"
        } else {
            "version fallback"
        }
    );
    supported
}

/// 只结束本应用当前进程创建并仍持有的 Harness 进程树。
/// **返回是否已确认持有的进程退出**（没有持有任何进程时也返回 `true`）。
/// 返回 `false` 时调用方不得删除该 Home 的 `.harness.pid`——那份标记是删除
/// Home 前守卫的唯一依据（见 `home_service_is_live`）。
fn terminate_owned_process() -> bool {
    let pid = OWNED_PROCESS_ID.swap(0, Ordering::SeqCst);
    if pid == 0 {
        return true;
    }

    #[cfg(windows)]
    {
        use windows_sys::Win32::Foundation::CloseHandle;
        use windows_sys::Win32::System::Threading::WaitForSingleObject;
        const WAIT_TIMEOUT_CODE: u32 = 0x0000_0102;
        let handle_value = OWNED_PROCESS_HANDLE.swap(0, Ordering::SeqCst);
        if handle_value == 0 {
            // 拿不到真实句柄就无法安全归属 PID（可能已被复用）：既不 taskkill，
            // 也不能声称已经结束——让调用方保留标记。
            log::warn!("No process handle for owned Harness pid {pid}; not killing blindly");
            return false;
        }
        let handle = handle_value as windows_sys::Win32::Foundation::HANDLE;
        // 真实句柄已结束说明 PID 可能已复用，此时绝不调用 taskkill。
        if unsafe { WaitForSingleObject(handle, 0) } != WAIT_TIMEOUT_CODE {
            unsafe { CloseHandle(handle) };
            return true;
        }
        let killed = kill_pid_tree(pid);
        unsafe {
            WaitForSingleObject(handle, 5_000);
            CloseHandle(handle);
        }
        killed
    }

    #[cfg(unix)]
    {
        kill_pid_tree(pid)
    }
}

/// 结束进程树（Windows `taskkill /PID <pid> /T /F`；Unix 负 PID 进程组，与
/// 启动时 `process_group(0)` 对应）。调用方需先确认 PID 确实指向目标进程。
///
/// **返回是否已确认目标进程退出。** 返回 `false` 时进程可能仍在运行，调用方
/// **不得**据此删除 `.harness.pid` 之类的存活证据——那份标记是删除 Home 前守卫
/// 的唯一依据（见 `home_service_is_live`），抹掉它等于让守卫失去依据。
pub(crate) fn kill_pid_tree(pid: u32) -> bool {
    #[cfg(windows)]
    {
        let mut cmd = Command::new("taskkill");
        cmd.args(["/PID", &pid.to_string(), "/T", "/F"]);
        use std::os::windows::process::CommandExt;
        cmd.creation_flags(0x08000000);
        // 不继承本进程的 stdin：GUI 进程下继承来的句柄可能让子命令挂起。
        cmd.stdin(Stdio::null());
        cmd.stdout(Stdio::null());
        cmd.stderr(Stdio::null());
        if let Err(e) = cmd.output() {
            log::error!("Failed to stop Harness process tree {pid}: {e}");
        }
        // taskkill 的退出码在 PID 已消失、权限不足、PID 已被复用等情况下都可能非零，
        // 不能当结论用。这里等进程真正消失，只把"确认已退出"当作成功。
        wait_pid_gone(pid, std::time::Duration::from_secs(5))
    }

    #[cfg(unix)]
    {
        // Harness 根进程启动在独立进程组中，负 PID 只作用于该进程树。
        // 分阶段升级信号强度，每一步都确认进程是否已真正消失。
        let group = format!("-{pid}");
        let _ = Command::new("kill").args(["-TERM", "--", &group]).output();
        if wait_pid_gone(pid, std::time::Duration::from_secs(5)) {
            return true;
        }
        let _ = Command::new("kill").args(["-KILL", "--", &group]).output();
        if wait_pid_gone(pid, std::time::Duration::from_secs(5)) {
            return true;
        }
        log::error!("Process tree {pid} is still alive after SIGKILL");
        false
    }
}

/// 轮询等待指定 PID 消失，返回是否在期限内确认退出。
///
/// 复用 `is_pid_alive`（Windows 用 `OpenProcess` 句柄、Unix 用 `kill -0`），
/// 因此不需要为"等进程退出"再引入一套平台 API。本函数在同步上下文里调用。
fn wait_pid_gone(pid: u32, timeout: std::time::Duration) -> bool {
    let deadline = std::time::Instant::now() + timeout;
    loop {
        if !is_pid_alive(pid) {
            return true;
        }
        if std::time::Instant::now() >= deadline {
            return false;
        }
        std::thread::sleep(std::time::Duration::from_millis(100));
    }
}

pub fn has_owned_process() -> bool {
    OWNED_PROCESS_ID.load(Ordering::SeqCst) != 0
}

fn record_process_exit(app_handle: &AppHandle, pid: u32, exit_code: Option<u32>) {
    if OWNED_PROCESS_ID
        .compare_exchange(pid, 0, Ordering::SeqCst, Ordering::SeqCst)
        .is_err()
    {
        return;
    }
    let port = RUNTIME_PORT.swap(0, Ordering::SeqCst);
    match exit_code {
        Some(code) => log::warn!(
            "Owned Harness process {pid} exited with code {code} (port {port}); service stopped"
        ),
        None => log::warn!(
            "Owned Harness process {pid} exited (exit code unavailable, port {port}); service stopped"
        ),
    }
    status::set_status(status::Status::Stopped);
    status::emit_status(app_handle);
}

/// 结束所有从本应用 dsh 安装目录启动的 Harness 服务进程（含历史崩溃残留的孤儿实例）。
///
/// 只停本应用当前持有的进程不够：`.harness.pid` 标记只记录最近一次会话的 PID，
/// 应用多次崩溃/强杀（任务管理器结束等）会遗留多个孤儿 dsh 进程、端口一路漂移
/// （3080→3081→…），`sweep_orphan_harness` 每次只能回收最近一个，更早的孤儿
/// 会持续占用 `dependencies/dsh` 目录的文件句柄（node 以该目录为 cwd 且模块
/// DLL 加载在内存），更新切换目录时触发 os error 32（INSTALL_BACKUP_FAILED）。
///
/// 命令行为本应用 dsh 入口路径（`...\dependencies\dsh\node_modules\...\bin.js`）
/// 的 node 进程可判定为本应用的服务实例——路径精确匹配不会误杀用户其它 node
/// 程序，因此可安全地全部结束（taskkill /T /F）。
pub fn terminate_stale_harness_processes(app_handle: &tauri::AppHandle) {
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        let dsh_bin_path = config::get_dsh_binary_path(app_handle);
        let Some(dsh_bin) = dsh_bin_path.to_str() else {
            return;
        };
        // 进程名过滤保证 PowerShell 自身（其命令行同样包含该路径）不被误杀；
        // 路径中的单引号按 PS 字符串字面量规则转义，避免用户目录含 `'` 时语法错误。
        let escaped = dsh_bin.replace('\'', "''");
        let script = format!(
            "Get-CimInstance Win32_Process -Filter \"Name = 'node.exe'\" | Where-Object {{ $_.CommandLine -like '*{escaped}*' }} | Select-Object -ExpandProperty ProcessId"
        );
        let Ok(output) = Command::new("powershell")
            .args(["-NoProfile", "-NonInteractive", "-Command", &script])
            .creation_flags(0x08000000)
            .output()
        else {
            log::error!("Failed to enumerate stale Harness service processes");
            return;
        };
        let mut found = 0;
        for line in String::from_utf8_lossy(&output.stdout).lines() {
            let Ok(pid) = line.trim().parse::<u32>() else {
                continue;
            };
            found += 1;
            log::warn!("Terminating stale Harness service process {pid} (from dsh install dir)");
            if !kill_pid_tree(pid) {
                log::error!("Stale Harness service process {pid} was not confirmed dead");
            }
        }
        if found > 0 {
            // 与 stop() 同理：taskkill 返回后 DLL 句柄的释放还有短暂滞后，
            // 让出一点时间避免紧随其后的目录切换撞上残留锁。
            std::thread::sleep(std::time::Duration::from_millis(800));
        }
    }
    #[cfg(not(windows))]
    {
        // Unix 允许对打开中的文件重命名，孤儿进程不阻塞更新切换，无需处理。
        let _ = app_handle;
    }
}

// ---------------------------------------------------------------------------
// 孤儿 Harness 清扫：崩溃/强杀残留实例的识别与回收（issue #34 关联现象）
// ---------------------------------------------------------------------------

const HARNESS_PID_FILE: &str = ".harness.pid";

/// 孤儿清扫用的 PID/端口标记文件路径（$DSH_HOME/.harness.pid，两行：PID、端口）。
///
/// 应用被强杀（崩溃、任务管理器结束等）时无法执行退出清理，其 Harness 子进程
/// 会继续占用端口；下一次启动只能一路漂移端口（3080→3081→…）并触发服务端
/// "already running"，表现为应用"坏掉"。启动前据此文件识别并清理这类残留。
fn harness_pid_path(app_handle: &tauri::AppHandle) -> std::path::PathBuf {
    home_harness_marker_path(&config::get_dsh_data_path(app_handle))
}

/// 指定 Home 下的 PID/端口标记路径。删除 Home 前的守卫要按实例 Home 取标记，
/// 不能复用只指向当前活动 Home 的 `harness_pid_path`。
pub fn home_harness_marker_path(home: &std::path::Path) -> std::path::PathBuf {
    home.join(HARNESS_PID_FILE)
}

/// 解析指定 Home 的标记内容，返回 (PID, 端口)。标记缺失或不可解析时为 None。
pub fn read_home_service_marker(home: &std::path::Path) -> Option<(u32, u16)> {
    let text = fs::read_to_string(home_harness_marker_path(home)).ok()?;
    let mut lines = text.lines();
    let pid = lines.next()?.trim().parse::<u32>().ok()?;
    let port = lines.next()?.trim().parse::<u16>().ok()?;
    Some((pid, port))
}

/// 进程是否存活。Windows 以 OpenProcess 句柄判定，拒绝访问说明进程存在只是权限
/// 不足；Unix 以 `kill -0` 判定。探测失败按不存活处理，调用方自行决定保守策略。
fn is_pid_alive(pid: u32) -> bool {
    if pid == 0 {
        return false;
    }

    #[cfg(windows)]
    {
        use windows_sys::Win32::Foundation::{CloseHandle, ERROR_ACCESS_DENIED};
        use windows_sys::Win32::System::Threading::{
            OpenProcess, PROCESS_QUERY_LIMITED_INFORMATION,
        };
        unsafe {
            let handle = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, 0, pid);
            if handle.is_null() {
                return std::io::Error::last_os_error().raw_os_error()
                    == Some(ERROR_ACCESS_DENIED as i32);
            }
            let _ = CloseHandle(handle);
            true
        }
    }

    #[cfg(not(windows))]
    {
        Command::new("kill")
            .args(["-0", "--", &pid.to_string()])
            .output()
            .is_ok_and(|output| output.status.success())
    }
}

/// 删除 Home 前的最终守卫：该 Home 是否仍有存活的 DSH 服务，返回其 PID。
///
/// 只看磁盘标记与进程活性，不看本进程的宿主表——启动器崩溃或被强杀后，遗留的
/// 宿主与 DSH 子进程在 `INSTANCE_HOSTS` 中不可见，却仍在写这个 Home。PID 复用的
/// 极端情况会误判为存活，代价是拒绝删除，而不是删掉正在使用的用户数据。
pub fn home_service_is_live(home: &std::path::Path) -> Option<u32> {
    let (pid, port) = read_home_service_marker(home)?;
    if !is_pid_alive(pid) {
        log::debug!(
            "stale harness marker under {}: pid {pid} (port {port}) is no longer alive",
            home.display()
        );
        return None;
    }
    Some(pid)
}

/// 记录本次启动的 Harness PID 与端口，供下次启动清扫孤儿用。
fn persist_harness_pid(app_handle: &tauri::AppHandle, pid: u32, port: u16) {
    let path = harness_pid_path(app_handle);
    if let Some(dir) = path.parent() {
        let _ = fs::create_dir_all(dir);
    }
    let _ = fs::write(&path, format!("{pid}\n{port}\n"));
}

/// 启动前清扫上次崩溃残留的孤儿 Harness。端口与 PID 双重确认后才动手：
/// - 标记进程已死 → 仅清理陈旧标记；
/// - 端口空闲但标记进程仍存活 → 保留标记不动；
/// - 端口占用者正是标记中的 PID → 本应用残留，结束其进程树并清标记；
/// - 其余情况（标记不可解析、端口被其他程序占用、无法探测占用者）一律不动，
///   绝不凭端口猜进程、绝不杀未知进程。
pub fn sweep_orphan_harness(app_handle: &tauri::AppHandle) {
    if has_owned_process() {
        return;
    }
    // 所有实例共享同一运行时路径，路径相同不意味着进程是孤儿。
    // 启动期间只能核验此 Home 的 PID 标记，禁止全局清扫其他实例。
    let pid_file = harness_pid_path(app_handle);
    let Ok(text) = fs::read_to_string(&pid_file) else {
        return;
    };
    let mut lines = text.lines();
    let (Some(pid), Some(port)) = (
        lines.next().and_then(|l| l.trim().parse::<u32>().ok()),
        lines.next().and_then(|l| l.trim().parse::<u16>().ok()),
    ) else {
        // 标记内容不可解析：陈旧垃圾，清掉即可
        let _ = fs::remove_file(&pid_file);
        return;
    };
    if !is_port_in_use(port) {
        // 端口空闲不等于进程已退出：可能崩溃在监听之前、或标记里的端口本就失真。
        // 同一份标记还是删除 Home 前 home_service_is_live 的唯一依据，这里凭端口
        // 把它删掉，等于每次启动都提前抹掉守卫的证据。没有端口要回收时保留即可。
        if is_pid_alive(pid) {
            return;
        }
        // 端口已释放且标记进程已确认退出：残留实例早已自行退出，仅清理标记
        let _ = fs::remove_file(&pid_file);
        return;
    }
    if port_owner_pid(port) != Some(pid) {
        // 端口占用者不是我们落盘的进程（或探测不到）：可能是其他程序，不动
        return;
    }
    log::warn!("Sweeping orphaned Harness process {pid} (port {port}) left by a previous session");
    if kill_pid_tree(pid) {
        let _ = fs::remove_file(&pid_file);
    } else {
        // 未能确认进程已退出：保留标记。它既是下次清扫的线索，也是删除 Home 前
        // 守卫的唯一依据；在这里删掉会让两者同时失效。
        log::error!(
            "Orphaned Harness process {pid} was not confirmed dead; keeping {} for the next sweep and the delete guard",
            pid_file.display()
        );
    }
}

/// 从本地地址列取出端口号（`127.0.0.1:3080` / `[::1]:3080` 两种形态）。
fn netstat_local_port(local: &str) -> Option<u16> {
    local.rsplit_once(':')?.1.parse().ok()
}

/// 从 `netstat -ano` 输出里找出处于 LISTENING、且本地端口匹配的进程 PID。
///
/// **必须按解析出的端口值比较，不能用 `ends_with` 比较 `":{port}"**：后者会把
/// `13080` 这类以 `3080` 结尾的端口误判成 `3080`，于是清扫可能去结束一个
/// 与本次目标无关的进程。端口比较是纯值比较，与 IPv4/IPv6 书写无关。
fn port_owner_pid_in_netstat(text: &str, port: u16) -> Option<u32> {
    for line in text.lines() {
        let fields: Vec<&str> = line.split_whitespace().collect();
        if fields.len() < 5 || fields[0] != "TCP" {
            continue;
        }
        // 本地地址在 fields[1]，状态在 fields[3]，PID 在 fields[4]
        if netstat_local_port(fields[1]) != Some(port) {
            continue;
        }
        if fields[3] == "LISTENING" {
            return fields[4].parse().ok();
        }
    }
    None
}

/// 占用指定端口的进程 PID（LISTENING 状态）。
/// - Windows：`netstat -ano` 解析；
/// - Unix：`lsof -ti tcp:<port>`，不可用时返回 None。
/// 返回 None 视为"无法确认"，调用方不会因此杀任何进程。
fn port_owner_pid(port: u16) -> Option<u32> {
    #[cfg(windows)]
    {
        let mut cmd = Command::new("netstat");
        cmd.arg("-ano");
        // 与其它 Windows 子进程一致：GUI 父进程下不得弹出控制台窗口。
        use std::os::windows::process::CommandExt;
        cmd.creation_flags(0x08000000);
        cmd.stdout(Stdio::piped());
        cmd.stderr(Stdio::null());
        let output = cmd.output().ok()?;
        port_owner_pid_in_netstat(&String::from_utf8_lossy(&output.stdout), port)
    }
    #[cfg(not(windows))]
    {
        // lsof 在 macOS 默认可用、Linux 常缺失；缺失时跳过清扫（返回 None）
        let output = Command::new("lsof")
            .args(["-ti", &format!("tcp:{port}")])
            .output()
            .ok()?;
        if !output.status.success() {
            return None;
        }
        String::from_utf8_lossy(&output.stdout)
            .lines()
            .next()
            .and_then(|l| l.trim().parse().ok())
    }
}

/// Windows RedirectionGuard（错误码 448 = ERROR_UNTRUSTED_MOUNT_POINT）逃逸重拉的标记路径。
fn relaunch_marker_path(app_handle: &tauri::AppHandle) -> std::path::PathBuf {
    config::get_base_dir(app_handle).join(".dsh-relaunch-448")
}

/// 探测 dsh 入口在当前进程上下文下的打开错误码（None=可打开）。
///
/// 448 只在「进程继承 RedirectionGuard 强制执行」时出现；干净上下文（父进程为
/// explorer 等普通进程）下 Level-1 符号链接可正常穿越。
fn dsh_bin_open_error(app_handle: &tauri::AppHandle) -> Option<i32> {
    std::fs::File::open(config::get_dsh_binary_path(app_handle))
        .err()
        .and_then(|e| e.raw_os_error())
}

/// 通过 explorer 转交启动请求，脱离 RedirectionGuard 强制执行上下文后退出本进程。
///
/// Windows 11 25H2 的 RedirectionGuard 对「非提权进程创建的符号链接/联接点」盖信任章，
/// 而安装器（msiexec/RestartManager 自动重开）会在自身进程启用强制执行并随进程树继承，
/// 导致新实例跨越 pnpm 符号链接链打开 bin.js 时持续报 448——实测与等待时长无关、
/// 永不自行恢复（issue #35）。应用无法在运行时关闭继承的策略，只能脱离被污染的进程树：
/// 把启动请求转交给 explorer（单实例壳进程，干净上下文），由 explorer 创建新实例，
/// 其父进程即 explorer，不再继承强制执行（实测：explorer.exe <exe> 的子进程父进程为
/// explorer.exe，而非转交发起者）。标记文件用于防死循环：若上次重拉未逃逸
/// （explorer 未运行等），本次回退到常规缺失处理（复位 installed 走安装流程）。
#[cfg(windows)]
fn relaunch_via_shell_escape(app_handle: &tauri::AppHandle) {
    let marker = relaunch_marker_path(app_handle);
    if marker.exists() {
        let _ = std::fs::remove_file(&marker);
        log::warn!("RedirectionGuard(448) relaunch did not escape, falling back to normal missing handling");
        return;
    }
    let _ = std::fs::write(&marker, b"1");
    let Ok(exe) = std::env::current_exe() else {
        log::warn!("RedirectionGuard(448) detected but current_exe unavailable, falling back");
        return;
    };
    match std::process::Command::new("explorer.exe").arg(&exe).spawn() {
        Ok(_) => {
            log::warn!(
                "RedirectionGuard(448) detected, relaunching via explorer to escape enforced context: {}",
                exe.display()
            );
            // 短暂让出后退出，避免与新实例产生单实例冲突
            std::thread::sleep(std::time::Duration::from_millis(300));
            std::process::exit(0);
        }
        Err(e) => {
            log::warn!(
                "RedirectionGuard(448) detected but explorer spawn failed ({e}), falling back"
            );
        }
    }
}

pub fn runtime_port() -> Option<u16> {
    u16::try_from(RUNTIME_PORT.load(Ordering::SeqCst))
        .ok()
        .filter(|port| *port != 0)
}

fn runtime_web_url_slot() -> &'static Mutex<Option<String>> {
    RUNTIME_WEB_URL.get_or_init(|| Mutex::new(None))
}

pub fn runtime_web_url() -> Option<String> {
    runtime_web_url_slot()
        .lock()
        .unwrap_or_else(|error| error.into_inner())
        .clone()
}

pub(crate) fn capture_web_url(line: &str) {
    let Some(candidate) = line
        .split_whitespace()
        .find(|part| part.starts_with("http://") || part.starts_with("https://"))
    else {
        return;
    };
    let Ok(url) = reqwest::Url::parse(candidate) else {
        return;
    };
    let Some(port) = runtime_port() else {
        return;
    };
    let loopback = matches!(url.host_str(), Some("127.0.0.1" | "localhost" | "::1"));
    let has_token = url
        .query_pairs()
        .any(|(key, value)| key == "token" && !value.is_empty());
    if url.scheme() == "http" && loopback && url.port_or_known_default() == Some(port) && has_token
    {
        *runtime_web_url_slot()
            .lock()
            .unwrap_or_else(|error| error.into_inner()) = Some(url.into());
    }
}

pub(crate) fn redact_web_url(line: &str) -> String {
    let Some(candidate) = line
        .split_whitespace()
        .find(|part| part.starts_with("http://") || part.starts_with("https://"))
    else {
        return line.to_string();
    };
    let Ok(mut url) = reqwest::Url::parse(candidate) else {
        return line.to_string();
    };
    let has_token = url.query_pairs().any(|(key, _)| key == "token");
    if !has_token {
        return line.to_string();
    }
    url.set_query(Some("token=[REDACTED]"));
    line.replacen(candidate, url.as_str(), 1)
}

/// 检测并启动 Harness 服务
pub async fn start(app_handle: tauri::AppHandle) -> Result<(), String> {
    let setting = config::get_store_dat_setting(&app_handle);
    let node_binary_path = config::get_dsh_node_path(&app_handle);
    let dsh_binary_path = config::get_dsh_binary_path(&app_handle);

    if !setting.installed {
        log::debug!("Harness not installed, skipping startup");
        return Ok(());
    }
    if !node_binary_path.exists() || !dsh_binary_path.exists() {
        // Windows RedirectionGuard(448)：安装器继承的强制执行上下文永不自行恢复，
        // 先尝试通过 explorer 逃逸重拉（见 relaunch_via_shell_escape 注释），
        // 成功则本进程退出；未命中（重拉未逃逸/非 448）才走常规缺失处理。
        #[cfg(windows)]
        if dsh_bin_open_error(&app_handle) == Some(448) {
            relaunch_via_shell_escape(&app_handle);
        }
        let mut setting = config::get_store_dat_setting(&app_handle);
        setting.installed = false;
        config::set_store_dat_setting(&app_handle, setting);
        // 状态变更需要 info 级落盘：这是「store 显示未安装」的源头之一
        // （核心文件短暂缺失被复位），自更新后自动重开走进安装分支多由此触发。
        log::info!("Runtime files missing (node/dsh), resetting installed flag");
        return Ok(());
    }

    if has_owned_process() {
        log::info!("Owned Harness process is already running");
        status::set_status(status::Status::Running);
        status::emit_status(&app_handle);
        return Ok(());
    }

    // 清理 RedirectionGuard(448) 逃逸重拉标记：本进程正常走到启动说明处于干净上下文，
    // 移除标记保证下次自更新后仍能触发逃逸重拉。
    #[cfg(windows)]
    let _ = std::fs::remove_file(relaunch_marker_path(&app_handle));

    log::info!("Starting Harness service");
    status::set_status(status::Status::Starting);
    status::emit_status(&app_handle);
    launch(app_handle).await?;
    // 之后由 scheduler/task/tick_check_dsh_process/mod.rs 检测状态

    Ok(())
}

/// 重启 Harness 服务
pub async fn restart(app_handle: tauri::AppHandle) -> Result<(), String> {
    log::info!("Restarting Harness service");

    // 1. 停止现有服务
    stop(app_handle.clone()).await?;

    // 2. 重新启动
    start(app_handle).await?;

    Ok(())
}

/// 启动 Harness 服务进程
pub async fn launch(app_handle: tauri::AppHandle) -> Result<(), String> {
    let setting = config::get_store_dat_setting(&app_handle);
    let instance = config::instance::active()
        .ok_or_else(|| "INSTANCE_NOT_SELECTED: select an instance before launch".to_string())?;
    let node_binary_path = config::get_dsh_node_path(&app_handle);
    let dsh_binary_path = config::get_dsh_binary_path(&app_handle);

    log::debug!("Checking Node.js path: {:?}", node_binary_path);
    if !node_binary_path.exists() {
        log::error!("Node.js not installed");
        return Err("NODE_NOT_FOUND: Node.js not installed".to_string());
    }
    log::debug!("Checking Harness path: {:?}", dsh_binary_path);
    if !dsh_binary_path.exists() {
        log::error!("Harness not installed");
        return Err("HARNESS_NOT_FOUND: Harness not installed".to_string());
    }

    // 避免重复启动（配合启动守卫，确保并发调用只拉起一个进程）
    if has_owned_process() {
        log::info!("Owned Harness process is already running, skipping launch");
        return Ok(());
    }
    if LAUNCH_GUARD
        .compare_exchange(false, true, Ordering::SeqCst, Ordering::SeqCst)
        .is_err()
    {
        log::info!("Harness launch already in progress, skipping");
        return Ok(());
    }
    let _launch_guard = LaunchGuard;

    // 端口属于本次运行状态：协作编排由启动器先分配固定端口，其余场景
    // 从推荐端口开始找空闲值；两种都不写回永久设置。
    let available_port = match requested_port() {
        Some(port) => port,
        None => find_available_port(setting.port)?,
    };
    RUNTIME_PORT.store(available_port as u32, Ordering::SeqCst);
    *runtime_web_url_slot()
        .lock()
        .unwrap_or_else(|error| error.into_inner()) = None;
    log::info!(
        "Instance {} allocated runtime port {}",
        instance.id,
        available_port
    );

    // 构造环境变量：隔离的 $DSH_HOME + 隐私默认（关闭遥测）
    let dsh_home = config::get_dsh_data_path(&app_handle);
    fs::create_dir_all(&dsh_home).map_err(|e| format!("create dsh home failed: {e}"))?;
    // DSH 只会自动创建内置的 web/headless profile；自定义实例 profile
    // 必须先有 package.json，否则 CLI 会先打印地址再以 code 1 退出。
    config::instance::ensure_profile(&dsh_home, &instance.profile)?;

    // Windows 极简模式修复的自愈：插件已装入 profile 时确保 patch 挂载行与
    // minimal-win 用户 preset 落盘（幂等）。最佳努力：失败只告警，不阻断启动。
    if let Err(e) = win_inspector::apply(&app_handle) {
        log::warn!("win32 terminal support apply failed: {e}");
    }
    let mut envs: HashMap<String, String> = HashMap::new();
    envs.insert(
        "DSH_HOME".to_string(),
        dsh_home.to_string_lossy().into_owned(),
    );
    envs.insert("DSH_TELEMETRY_DISABLED".to_string(), "1".to_string());
    envs.insert("NO_COLOR".to_string(), "1".to_string());
    envs.insert("DSH_WEB_PORT".to_string(), available_port.to_string());

    // 扩展 PATH，让 dsh 及其子进程能找到 node；Windows 上再注入 Git Bash 的
    // bin 目录：persistent bash（--noprofile --norc）不执行 profile 脚本、PATH
    // 完全继承服务进程，若不含 Git 的 usr/bin，ls/sed/find 等 coreutils 全会
    // `command not found`（MSYS 运行时在部分环境下不会自动补 /usr/bin）。
    if let Some(node_dir) = node_binary_path.parent() {
        if let Some(existing_path) = std::env::var_os("PATH") {
            let git_dirs = win_inspector::git_bash_bin_dirs();
            // 只打印注入的前缀目录，完整 PATH 太长会刷屏
            for dir in &git_dirs {
                log::debug!("harness service PATH prepend: {}", dir.to_string_lossy());
            }
            let mut paths = vec![node_dir.to_path_buf()];
            paths.extend(git_dirs);
            paths.extend(std::env::split_paths(&existing_path));
            if let Ok(new_path) = std::env::join_paths(paths) {
                envs.insert("PATH".to_string(), new_path.to_string_lossy().into_owned());
            }
        }
    }

    // 日志文件（前端日志面板读取）。
    // 每次真实启动前轮转：只保留最近 3 次启动的日志，旧文件后退为
    // `dsh-web.log.1` / `dsh-web.log.2`，避免单文件随多次启动无限增长。
    let log_path = config::get_service_log_path(&app_handle);
    fs::create_dir_all(log_path.parent().unwrap_or(std::path::Path::new(".")))
        .map_err(|e| format!("create log dir failed: {e}"))?;
    utils::rotate_service_log(&log_path, 3);

    // DSH Web 默认可能打开系统浏览器；桌面端内嵌 WebView，因此依据已缓存的
    // CLI 能力探测结果追加 `--no-open`。运行时变化会自动使缓存失效。
    let no_open = refresh_web_capabilities(&app_handle);

    log::info!("Starting Harness process");

    // Windows 打包版是 GUI 进程（没有控制台）。直接以 CREATE_NO_WINDOW 启动
    // node 会让 dsh 派生的子进程各自新建可见控制台窗口（频繁闪烁 cmd 黑窗），
    // 因此 Windows 上改用“隐藏控制台”方式启动，见 win_spawn 模块。
    let spawn_result = {
        #[cfg(windows)]
        {
            let mut args: Vec<OsString> = vec![
                dsh_binary_path.as_os_str().to_os_string(),
                OsString::from("--profile"),
                OsString::from(&instance.profile),
                OsString::from("--host"),
                OsString::from("127.0.0.1"),
                OsString::from("--port"),
                OsString::from(available_port.to_string()),
            ];
            if no_open {
                args.push(OsString::from("--no-open"));
            }
            win_spawn::spawn_with_hidden_console_owned(
                &node_binary_path,
                &args,
                Some(&config::get_dsh_working_dir(&app_handle)),
                &envs,
            )
            .map(|(stdout, stderr, pid, handle)| {
                OWNED_PROCESS_ID.store(pid, Ordering::SeqCst);
                // 持有真实进程句柄直到退出；退出后仅在 PID 仍匹配时清空，避免复用。
                let handle_value = handle as usize;
                OWNED_PROCESS_HANDLE.store(handle_value, Ordering::SeqCst);
                let app_for_exit = app_handle.clone();
                std::thread::spawn(move || unsafe {
                    use windows_sys::Win32::Foundation::CloseHandle;
                    use windows_sys::Win32::System::Threading::{
                        GetExitCodeProcess, WaitForSingleObject, INFINITE,
                    };
                    let process_handle = handle_value as windows_sys::Win32::Foundation::HANDLE;
                    WaitForSingleObject(process_handle, INFINITE);
                    // 记录退出码：启动即崩溃（插件冲突等）时前端据此快速失败，
                    // 退出码也便于诊断问题
                    let mut exit_code: u32 = 0;
                    let exit_code = if GetExitCodeProcess(process_handle, &mut exit_code) != 0 {
                        Some(exit_code)
                    } else {
                        None
                    };
                    record_process_exit(&app_for_exit, pid, exit_code);
                    let owns_handle = OWNED_PROCESS_HANDLE
                        .compare_exchange(handle_value, 0, Ordering::SeqCst, Ordering::SeqCst)
                        .is_ok();
                    if owns_handle {
                        CloseHandle(process_handle);
                    }
                });
                (Some(stdout), Some(stderr), pid)
            })
        }
        #[cfg(not(windows))]
        {
            use std::os::unix::process::CommandExt;
            let mut cmd = Command::new(&node_binary_path);
            cmd.arg(&dsh_binary_path)
                .arg("--profile")
                .arg(&instance.profile)
                .arg("--host")
                .arg("127.0.0.1")
                .arg("--port")
                .arg(available_port.to_string());
            if no_open {
                cmd.arg("--no-open");
            }
            cmd.envs(&envs)
                .current_dir(config::get_dsh_working_dir(&app_handle))
                // 核心修正：提供一个空的 stdin 防止 setRawMode 报错
                .stdin(Stdio::null())
                // 使用管道捕获输出，以便在子线程中读取
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                // 独立进程组让停止操作只影响 Harness 及其后代。
                .process_group(0);
            cmd.spawn().map(|mut child| {
                let pid = child.id();
                let stdout = child.stdout.take();
                let stderr = child.stderr.take();
                OWNED_PROCESS_ID.store(pid, Ordering::SeqCst);
                let app_for_exit = app_handle.clone();
                std::thread::spawn(move || {
                    let code = child.wait().ok().and_then(|status| status.code());
                    record_process_exit(&app_for_exit, pid, code.map(|value| value as u32));
                });
                (stdout, stderr, pid)
            })
        }
    };

    match spawn_result {
        Ok((stdout, stderr, pid)) => {
            log::info!(
                "Harness process started successfully: pid={pid}, port={}",
                available_port
            );
            // 记录 PID+端口供下次启动清扫崩溃残留的孤儿实例（见 sweep_orphan_harness）
            persist_harness_pid(&app_handle, pid, available_port);
            spawn_output_readers(stdout, stderr, log_path);
            Ok(())
        }
        Err(e) => {
            log::error!("Failed to start process: {}", e);
            Err(format!("PROCESS_START_FAILED: {e}"))
        }
    }
}

/// 停止 Harness 服务
pub async fn stop(app_handle: tauri::AppHandle) -> Result<(), String> {
    log::info!("Stopping Harness service...");
    // 重置启动守卫，确保后续 launch 可以重新拉起；仅结束持有的根进程树。
    LAUNCH_GUARD.store(false, Ordering::SeqCst);
    let confirmed = terminate_owned_process();
    // 清理孤儿清扫标记：正常停止的实例不应被下次启动当作残留。
    // 只在确认进程已退出时才删——进程仍存活而标记被抹掉，等于让删除 Home 的
    // 守卫失去依据（见 `home_service_is_live`）。
    if confirmed {
        let _ = fs::remove_file(harness_pid_path(&app_handle));
    } else {
        log::warn!(
            "Harness process tree not confirmed dead; keeping .harness.pid as delete-guard evidence"
        );
    }
    RUNTIME_PORT.store(0, Ordering::SeqCst);

    // 给系统一点时间释放端口 (重要！)
    tokio::time::sleep(std::time::Duration::from_millis(800)).await;

    status::set_status(status::Status::Stopped);
    status::emit_status(&app_handle);
    Ok(())
}

/// 应用退出时同步回收 Harness 进程。
///
/// 退出路径上不更新状态、不做异步等待，只结束当前应用持有的 Harness 进程树。
pub fn stop_on_exit(app_handle: tauri::AppHandle, _port: u16) {
    // 退出路径同样只在确认进程已退出时清理标记。启动器本次没有持有进程时
    // `terminate_owned_process` 返回 true，行为与原先一致；但只要进程可能仍存活
    // （拿不到句柄、kill 未确认），就必须把标记留给下一次启动的清扫与删除守卫，
    // 而不是在这里抹掉。
    if terminate_owned_process() {
        let _ = fs::remove_file(harness_pid_path(&app_handle));
    } else {
        log::warn!("Harness process tree not confirmed dead on exit; keeping .harness.pid");
    }
}

/// 安装环境（Node.js 运行时 + 打包的 Harness 发行版）。
///
/// 返回是否真正落盘更新了 Harness（dsh 任务实际下载并解压）；仅重装
/// Node/pnpm 或全部任务被跳过时返回 false，供调用方决定是否重启页面。
pub async fn install(
    app_handle: &tauri::AppHandle,
    mut dsh_latest: Option<download::LatestDshPkg>,
) -> Result<bool, String> {
    log::info!("Starting installation process");
    // dsh 任务（index==1）实际下载解压时置 true
    let mut dsh_updated = false;

    // 安装前先停止本应用持有的 Harness 服务：运行中的 node 进程会把
    // 原生模块 DLL（如 sharp 的 libvips-42.dll）加载进内存并锁住文件，
    // 不停止的话覆盖解压必然失败（Windows os error 32）。
    // 进程归属以启动时记录的 PID 为准，不根据端口结束未知程序。
    if has_owned_process() {
        log::info!("Stopping running Harness service before installation");
        stop(app_handle.clone()).await?;
    }
    // 只停本应用持有的进程还不够：历史崩溃/强杀残留的孤儿 Harness 实例
    // （不在 .harness.pid 标记中）同样从 dependencies/dsh 启动、占用目录文件
    // 句柄，会导致更新切换目录失败（INSTALL_BACKUP_FAILED, os error 32）。
    // 按命令行路径精确清扫所有本应用 dsh 安装目录启动的进程。
    terminate_stale_harness_processes(app_handle);

    let window = app_handle
        .get_webview_window("main")
        .ok_or("Failed to get main window")?;
    log::debug!("Main window obtained");
    // 3 个任务 × 下载/解压 2 个阶段
    let mut tracker = download::ProgressTracker::new(&window, 6);
    let tasks: Vec<Box<dyn download::Installable>> = vec![
        Box::new(download::Nodejs),
        Box::new(download::Dsh),
        Box::new(download::Pnpm),
    ];
    log::info!("Task list created, {} tasks total", tasks.len());

    for (index, task) in tasks.iter().enumerate() {
        log::debug!("Processing task {}/{}", index + 1, tasks.len());
        // 已安装但版本/commit 与最新 release 不一致时强制重新下载。
        // 版本优先（与 resolve_update 的判定完全一致）：dsh 的 rc 发布会复用
        // 同一 git commit（record_commit 不变），只比 commit 会把 rc.8 之于
        // rc.7 误判为"已最新"而跳过下载——日志表现为"All installation tasks
        // completed"但实际什么都没下载，重启后仍是旧版，且前端丢掉更新提示。
        let outdated = index == 1
            && dsh_latest.as_ref().is_some_and(|info| {
                let installed_version = config::get_dsh_version(app_handle);
                let latest_version = download::parse_version_from_tag(&info.tag);
                // 版本号可解析且不同 → 必须更新；版本不可解析时退回 commit 比对
                let version_differs =
                    match (installed_version.as_deref(), latest_version.as_deref()) {
                        (Some(a), Some(b)) => a != b,
                        _ => false,
                    };
                version_differs
                    || config::get_dsh_pkg_commit(app_handle).as_deref()
                        != Some(info.commit.as_str())
            });
        if task.check_installed(app_handle) && !outdated {
            log::debug!(
                "Task {} already installed and up to date, skipping",
                index + 1
            );
            tracker.skip_phases(2);
            continue;
        }

        log::info!("Task {} not installed, starting installation", index + 1);

        // 1. 下载
        tracker.start_phase(
            "download",
            &format!(
                "{} {}",
                config::i18n::t("install.downloading"),
                task.title()
            ),
        );
        // 下载 URL 对 dsh 也是完全确定可算的（DSH_CORE_URL + 平台文件名），
        // 无需依赖 GitHub API 元数据；api.github.com 限流/被代理拦截时
        // （mac 首次启动常见）仍能拿到真实下载地址，避免整次安装被瞬时失败卡死。
        let url = task.get_download_url()?;
        log::debug!("Download URL: {}", url);
        // 取文件名用于解压类型判定；下载 URL 正常必含 '/'，但这里不 panic，
        // 防御性兜底为空串（后续 ensure_extract 会因无法判定类型而报错返回，
        // 不再让进程崩溃）。
        let name = url.rsplit('/').next().unwrap_or("").to_string();
        log::debug!("File name: {}", name);
        let buffer = download::download_file(&tracker, url).await?;
        log::info!("Download completed, file size: {} bytes", buffer.len());
        let expected_digest = match index {
            0 => download::fetch_node_sha256(task.get_download_url()?.as_str()).await?,
            1 => {
                // dsh 的 SHA-256 digest 只能来自 GitHub release asset 元数据
                // （安全设计，见 dsh_INTEGRITY_UNAVAILABLE）。首次安装时该元数据
                // 可能因 api.github.com 限流/网络抖动而缺失（mac 首次启动常见，
                // issue #31），这里带退避重取，避免启动被瞬时失败卡死。
                if dsh_latest.is_none() {
                    for attempt in 0..3 {
                        match download::fetch_latest_dsh_pkg_info().await {
                            Ok(info) => {
                                dsh_latest = Some(info);
                                break;
                            }
                            Err(e) if attempt < 2 => {
                                log::warn!(
                                    "Retrying dsh release metadata fetch ({}/3), will retry: {}",
                                    attempt + 1,
                                    e
                                );
                                tokio::time::sleep(std::time::Duration::from_millis(
                                    500 * (attempt as u64 + 1),
                                ))
                                .await;
                            }
                            Err(e) => {
                                return Err(format!(
                                    "DSH_INTEGRITY_UNAVAILABLE: 无法获取 Harness 发行版的完整性校验信息（{}），请检查网络后重试",
                                    e
                                ));
                            }
                        }
                    }
                }
                dsh_latest
                    .as_ref()
                    .and_then(|info| info.digest.clone())
                    .ok_or_else(|| {
                        "DSH_INTEGRITY_UNAVAILABLE: trusted release digest is required".to_string()
                    })?
            }
            2 => config::PNPM_SHA256.to_string(),
            _ => return Err("INSTALL_TASK_INVALID: unknown install task".to_string()),
        };
        download::verify_sha256(&buffer, &expected_digest)?;
        log::info!("Download integrity verified for task {}", index + 1);
        tracker.end_phase();

        // 2. 解压
        tracker.start_phase(
            "extract",
            &format!("{} {}", config::i18n::t("install.extracting"), task.title()),
        );
        let dest = task.get_install_path(app_handle);
        log::debug!("Installation path: {:?}", dest);
        download::ensure_extract(&tracker, name, buffer, dest).await?;
        log::info!("Extraction completed");
        tracker.end_phase();

        // 记录本次安装对应的 release tag 与 commit，供下次启动比对
        if index == 1 {
            dsh_updated = true;
            if let Some(info) = &dsh_latest {
                config::set_dsh_pkg_commit(app_handle, info.commit.clone());
                config::set_dsh_pkg_tag(app_handle, info.tag.clone());
            }
        }
    }

    log::info!("All installation tasks completed");
    // type 供前端判定环境准备已结束：其后只剩拉起服务和等待端口。
    tracker.start_phase("done", &config::i18n::t("install.done"));
    tracker.update(
        100.0,
        config::i18n::t("install.done"),
        "All tasks completed".into(),
    );

    Ok(dsh_updated)
}

/// 健康检查（通过 Rust 代理，避免 WebView CORS 问题）
pub async fn proxy_health_check(port: u16) -> Result<String, String> {
    if !has_owned_process() {
        return Err("HARNESS_NOT_OWNED: no Harness process is owned by this app".to_string());
    }
    let client = reqwest::Client::builder()
        .timeout(config::HEALTH_CHECK_TIMEOUT)
        .build()
        .map_err(|e| e.to_string())?;

    for endpoint in [
        format!("http://127.0.0.1:{port}/"),
        format!("http://127.0.0.1:{port}/healthz"),
    ] {
        match client.get(&endpoint).send().await {
            Ok(response) => {
                let status = response.status();
                let body = response.text().await.unwrap_or_default();
                if status.is_success() {
                    return Ok(format!(
                        "healthy - {status} - {}",
                        body.chars().take(80).collect::<String>()
                    ));
                }
            }
            Err(err) => {
                log::debug!("Health check {endpoint}: {err}");
            }
        }
    }
    Err("HARNESS_NOT_READY: Harness service is not ready".to_string())
}

/// 等待 DSH Web 服务可访问（HTTP / 返回 200）。实例宿主窗口必须在服务真正
/// 监听后再加载地址，否则 WebView 会先展示“拒绝连接”且不会自动重试。
/// 失败时返回 false，调用方不得创建指向失效服务的窗口。
pub async fn wait_until_web_ready(port: u16, timeout: std::time::Duration) -> bool {
    let deadline = std::time::Instant::now() + timeout;
    let Ok(client) = reqwest::Client::builder()
        .no_proxy()
        .redirect(reqwest::redirect::Policy::none())
        .timeout(std::time::Duration::from_secs(2))
        .build()
    else {
        return false;
    };
    while std::time::Instant::now() < deadline {
        // 启动中的 Harness 若已退出，应立即让实例宿主失败退出；继续等满超时并
        // 创建 WebView 只会留下一个误导用户的 ERR_CONNECTION_REFUSED 窗口。
        if !has_owned_process() {
            return false;
        }
        if let Some(url) = runtime_web_url() {
            if authenticated_web_ready(&client, &url).await {
                return true;
            }
        } else {
            let url = crate::config::get_dsh_service_url(port);
            if let Ok(response) = client.get(url).send().await {
                if response.status().is_success() {
                    return true;
                }
            }
        }
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
    }
    false
}

/// 新版 DSH 用启动 URL 换取 Cookie 后跳回首页。健康检查只将 Cookie
/// 发回同一来源的根路径，避免默认跳转丢失 Cookie 后反复得到 401。
async fn authenticated_web_ready(client: &reqwest::Client, url: &str) -> bool {
    let Ok(response) = client.get(url).send().await else { return false; };
    if response.status().is_success() {
        return true;
    }
    let location = response.headers().get(reqwest::header::LOCATION)
        .and_then(|value| value.to_str().ok());
    // DSH 0.1.7-rc.1 redirects to `./`; earlier builds used `/`.
    // Accept only these same-origin root paths before forwarding the session cookie.
    if response.status() != reqwest::StatusCode::SEE_OTHER
        || !matches!(location, Some("/" | "./"))
    {
        return false;
    }
    let cookies = response.headers().get_all(reqwest::header::SET_COOKIE)
        .iter().filter_map(|value| value.to_str().ok())
        .filter_map(|value| value.split(';').next())
        .collect::<Vec<_>>().join("; ");
    if cookies.is_empty() { return false; }
    let Ok(mut root) = reqwest::Url::parse(url) else { return false; };
    root.set_path("/");
    root.set_query(None);
    root.set_fragment(None);
    client.get(root).header(reqwest::header::COOKIE, cookies).send().await
        .is_ok_and(|response| response.status().is_success())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn readiness_exchanges_launch_token_for_cookie() {
        use std::io::{Read, Write};
        for location in ["/", "./"] {
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = listener.local_addr().unwrap();
        let location = location.to_string();
        let server = std::thread::spawn(move || {
            for step in 0..2 {
                let (mut stream, _) = listener.accept().unwrap();
                stream.set_read_timeout(Some(std::time::Duration::from_secs(3))).unwrap();
                let mut buffer = [0; 4096];
                let count = stream.read(&mut buffer).unwrap();
                let request = String::from_utf8_lossy(&buffer[..count]).to_lowercase();
                if step == 0 {
                    assert!(request.starts_with("get /?token=test "));
                    stream.write_all(format!("HTTP/1.1 303 See Other\r\nLocation: {location}\r\nSet-Cookie: session=valid; HttpOnly\r\nContent-Length: 0\r\nConnection: close\r\n\r\n").as_bytes()).unwrap();
                } else {
                    assert!(request.starts_with("get / "));
                    assert!(request.contains("cookie: session=valid"));
                    stream.write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\nConnection: close\r\n\r\n").unwrap();
                }
            }
        });
        let client = reqwest::Client::builder().no_proxy()
            .redirect(reqwest::redirect::Policy::none())
            .timeout(std::time::Duration::from_secs(3)).build().unwrap();
        assert!(authenticated_web_ready(&client, &format!("http://{addr}/?token=test")).await);
        server.join().unwrap();
        }
    }
