    #[test]
    fn occupied_port_advances_to_a_free_port() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind occupied test port");
        let occupied = listener.local_addr().expect("read occupied port").port();
        let selected = find_available_port(occupied).expect("find next free port");
        assert!(selected > occupied);
        assert!(!is_port_in_use(selected));
    }

    #[test]
    fn no_open_supported_on_rc8_and_later() {
        assert!(version_supports_no_open("0.1.0-rc.8"));
        assert!(version_supports_no_open("0.1.0-rc.9"));
        assert!(version_supports_no_open("0.1.0"));
        assert!(version_supports_no_open("0.1.1-rc.1"));
        assert!(version_supports_no_open("v0.1.1-rc.1"));
        assert!(version_supports_no_open("0.2.0"));
    }

    #[test]
    fn no_open_absent_before_rc8() {
        assert!(!version_supports_no_open("0.1.0-rc.7"));
        assert!(!version_supports_no_open("0.1.0-rc.0"));
        assert!(!version_supports_no_open("0.0.9"));
    }

    #[test]
    fn no_open_unknown_version_is_conservative() {
        assert!(!version_supports_no_open(""));
        // rc 号缺失/非数字：无法判定，保守按不支持处理
        assert!(!version_supports_no_open("0.1.0-rc"));
        assert!(!version_supports_no_open("0.1.0-rc.a"));
        assert!(!version_supports_no_open("latest"));
    }

    #[test]
    fn captures_authenticated_loopback_web_url_and_redacts_log() {
        RUNTIME_PORT.store(3081, Ordering::SeqCst);
        *runtime_web_url_slot()
            .lock()
            .unwrap_or_else(|error| error.into_inner()) = None;
        let line = "dsh web: http://127.0.0.1:3081/?token=secret-value";

        capture_web_url(line);

        assert_eq!(
            runtime_web_url().as_deref(),
            Some("http://127.0.0.1:3081/?token=secret-value")
        );
        let redacted = redact_web_url(line);
        assert!(!redacted.contains("secret-value"));
        assert!(redacted.contains("REDACTED"));
    }

    #[test]
    fn netstat_local_port_handles_ipv4_and_ipv6_forms() {
        assert_eq!(netstat_local_port("127.0.0.1:3080"), Some(3080));
        assert_eq!(netstat_local_port("0.0.0.0:3080"), Some(3080));
        assert_eq!(netstat_local_port("[::1]:3080"), Some(3080));
        assert_eq!(netstat_local_port("[::]:3080"), Some(3080));
        // 非数字端口 / 空串：无法确认，返回 None
        assert_eq!(netstat_local_port("127.0.0.1:"), None);
        assert_eq!(netstat_local_port(""), None);
        assert_eq!(netstat_local_port("3080"), None);
    }

    /// 回归：清扫靠这个解析找"占用端口的那个 PID"。原实现用 `ends_with` 比较带尾部
    /// 空格的 `":{port} "`，而字段来自 `split_whitespace()`、**永远不可能以空格
    /// 结尾**，因此条件恒不匹配——Windows 上孤儿回收分支整条不可达。同一判据还会把
    /// `13080` 误认成 `3080`。
    #[test]
    fn netstat_port_owner_matches_the_exact_port_and_only_listening() {
        // 真实 `netstat -ano` 的形态：TCP <本地地址> <外部地址> <状态> <PID>
        let text = "活动连接\r\n\
            \x20 TCP    127.0.0.1:3081         0.0.0.0:0              LISTENING       4242\r\n\
            \x20 TCP    [::1]:3081             [::]:0                 LISTENING       4242\r\n\
            \x20 TCP    127.0.0.1:3080         0.0.0.0:0              LISTENING       1111\r\n\
            \x20 TCP    [::1]:13080            [::]:0                 LISTENING       9999\r\n\
            \x20 TCP    127.0.0.1:3080         127.0.0.1:52341        ESTABLISHED     7777\r\n";

        // 命中目标端口，取到的必须是 LISTENING 那个 PID（而不是 ESTABLISHED 的连接）
        assert_eq!(port_owner_pid_in_netstat(text, 3080), Some(1111));
        // 以 3080 结尾但不是 3080 的端口不得被误判
        assert_eq!(port_owner_pid_in_netstat(text, 3080), Some(1111));
        assert_eq!(port_owner_pid_in_netstat(text, 1308), None);
        assert_eq!(port_owner_pid_in_netstat(text, 13080), Some(9999));
        // 完全没出现的端口
        assert_eq!(port_owner_pid_in_netstat(text, 40000), None);
        // 空输出不得 panic
        assert_eq!(port_owner_pid_in_netstat("", 3080), None);
    }
